import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-integral-v9-auto';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='NORMAL';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);

 await evaluate(`(async()=>{
  const {createPilot}=await import('/docs/diario-ia/qa/yuna/piloto-base.mjs');
  let pilot=createPilot();window.audit={samples:[],events:[],snapshots:[],visited:[],renders:[],frames:[],retries:0,started:performance.now(),done:false};
  const visited=new Set(),seen=new Set();let nextX=0,lastStage='',lastSupport='',lastAge=-1;
  const pad={connected:true,axes:[0],buttons:Array.from({length:16},()=>({pressed:false}))};Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[pad]});
  const event=phase.audio.event.bind(phase.audio);phase.audio.event=type=>{const s=phase.state;audit.events.push({type,time:s.time,age:s.age,wall:(performance.now()-audit.started)/1000,x:s.player.x,y:s.player.y,support:s.player.support,terrain:s.player.terrain,hp:s.hp,panic:s.encounters.panic?.id,near:[...s.enemies,...s.encounters.bees,...s.encounters.worms].filter(e=>e.alive&&Math.abs(e.x-s.player.x)<200).map(e=>({id:e.id,type:e.type,x:e.x,y:e.y}))});event(type);};
  const update=phase.update.bind(phase);phase.update=dt=>{
   if(phase.reading()&&phase.state.story.cardAge>1.3){window.dispatchEvent(new KeyboardEvent('keydown',{code:'Enter'}));window.dispatchEvent(new KeyboardEvent('keyup',{code:'Enter'}));}const input=pilot(phase.state);pad.axes[0]=input.x;pad.buttons[0].pressed=input.jump;update(dt);const s=phase.state;
   if(s.player.onGround)visited.add(s.player.support);audit.visited=[...visited];
   const capture=label=>{const id=label+'-'+audit.snapshots.length;audit.snapshots.push({id,state:structuredClone(s)});};
   if(s.stage!==lastStage){capture('etapa-'+s.stage);lastStage=s.stage;}
   if(s.stage==='INTRO'&&Math.floor(s.age/5)!==lastAge){lastAge=Math.floor(s.age/5);capture('abertura-'+lastAge);}
   if(s.stage==='RUNNING'&&s.player.x>=nextX){capture('caminho');nextX=s.player.x+700;}
   for(const b of s.encounters.bees)if(['prepare','dive','return'].includes(b.phase)&&!seen.has(b.id+b.phase)){seen.add(b.id+b.phase);capture('abelha-'+b.phase);}
   for(const w of s.encounters.worms)if(w.exposure>.6&&!seen.has(w.id)){seen.add(w.id);capture(w.id);}
   if(s.encounters.panic&&!seen.has(s.encounters.panic.id)){seen.add(s.encounters.panic.id);capture(s.encounters.panic.id);}
   if(s.stage==='COMPLETE'&&s.story.endingDone&&s.age>=20){audit.done=true;game.setPaused(true);}
   if(audit.samples.length===0||s.time-audit.samples.at(-1).time>1)audit.samples.push({time:s.time,x:s.player.x,y:s.player.y,hp:s.hp,stage:s.stage,terrain:s.player.terrain,support:s.player.support,vx:s.player.vx,panic:s.encounters.panic?.id});
  };
  const render=phase.render.bind(phase);phase.render=()=>{const t=performance.now();render();audit.renders.push(performance.now()-t);if(audit.renders.length>60000)audit.renders.shift();};
  let last=0;const measure=now=>{if(last)audit.frames.push(now-last);last=now;if(!audit.done)requestAnimationFrame(measure);};requestAnimationFrame(measure);
  window.auditRetry=()=>{pilot=createPilot();audit.retries++;};phase.audio.unlock();game.setPaused(false);
 })()`);
 let copied=0,lastShot=0,lastStage='',pendingRetry=false;
 const started=Date.now();
 while(Date.now()-started<900000){
  await new Promise(r=>setTimeout(r,750));
  const progress=await evaluate(`(()=>{const s=phase.state;return{wall:(performance.now()-audit.started)/1000,time:s.time,age:s.age,x:s.player.x,hp:s.hp,stage:s.stage,ready:phase.ready,paused:game.isPaused(),done:audit.done,snapshots:audit.snapshots.length,retries:audit.retries,dialogs:[...document.querySelectorAll('dialog[open]')].map(d=>({id:d.id,text:d.innerText})),error:phase.error};})()`);
  await writeFile(out+'/progresso.json',JSON.stringify(progress,null,2));
  if(progress.snapshots>copied){
   const frames=await evaluate(`audit.snapshots.slice(${copied}).map(x=>({id:x.id,state:x.state}))`);
   for(const frame of frames)await writeFile(out+'/'+frame.id+'.json',JSON.stringify(frame.state));copied=progress.snapshots;
  }
  if(progress.wall-lastShot>6||progress.stage!==lastStage){const shot=await call('Page.captureScreenshot',{format:'png'});const file=String(Math.floor(progress.wall)).padStart(4,'0')+'-'+progress.stage+'-'+Math.round(progress.x)+'.png';await writeFile(out+'/'+file,Buffer.from(shot.result.data,'base64'));lastShot=progress.wall;lastStage=progress.stage;}
  if(progress.stage==='GAME_OVER'&&!pendingRetry){pendingRetry=true;await new Promise(r=>setTimeout(r,500));await evaluate(`(async()=>{const decline=document.querySelector('#btn-decline-easy');if(decline&&decline.getBoundingClientRect().width)decline.click();await new Promise(r=>setTimeout(r,300));const retry=document.querySelector('#btn-retry');if(!retry)throw Error('Sem botão de retry');retry.click();auditRetry();})()`);}
  if(progress.stage==='RUNNING')pendingRetry=false;
  if(progress.done)break;
 }
 const report=await evaluate(`(()=>{const s=phase.state,sorted=audit.frames.filter(x=>x<1000).sort((a,b)=>a-b),pct=q=>sorted[Math.floor(sorted.length*q)];return{...audit,final:{stage:s.stage,x:s.player.x,hp:s.hp,age:s.age},raf:{p50:pct(.5),p95:pct(.95),p99:pct(.99)},wall:(performance.now()-audit.started)/1000};})()`);
 await writeFile(out+'/resultado.json',JSON.stringify(report,null,2));await writeFile('docs/diario-ia/qa-resultados/yuna/auditoria-integral.json',JSON.stringify(report,null,2));
 console.log(JSON.stringify({final:report.final,retries:report.retries,wall:report.wall,raf:report.raf,events:report.events.length,snapshots:report.snapshots.length}));
 if(!report.done||report.final.stage!=='COMPLETE')throw Error('Percurso não concluiu no limite; resultado parcial preservado.');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
